// node --test render/image-single-golden.test.mjs
// The SINGLE placement of the image and edit graphs is the graph the builders made before placements existed, node for node.
//
// render/testdata/image-single-graphs.json holds fourteen results (SDXL, HiDream-O1, krea2 single and pooled, Qwen-Image 2512 as GGUF and as
// safetensors, Qwen-Image-2.1 int8 and bf16, and four edit graphs) with the arguments that made them. They were generated by comfy-render.mjs
// buildRenderGraph and comfy-edit.mjs planEdit as they stood at the 0.181.0 branch tip (b8e324ed), BEFORE `--placement` was added, and are not
// regenerated from the current code: a change that moves a node of a no-placement graph fails here and must say so. This is what makes "a box
// that does not set the placement renders exactly what it rendered" a tested statement and not a hope, and it is the sibling of
// wan-single-golden.test.mjs for the Wan graph.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { buildRenderGraph } from "./comfy-render.mjs";
import { planEdit } from "./comfy-edit.mjs";

const golden = JSON.parse(readFileSync(new URL("./testdata/image-single-graphs.json", import.meta.url), "utf8"));
const names = Object.keys(golden);

const rebuild = (e, extraFlags = {}) => {
  if (e.via === "render") return buildRenderGraph({ pos: e.pos, flags: { ...e.flags, ...extraFlags }, env: e.env, random: () => 0.5 });
  const plan = planEdit({ pos: e.pos, flags: { ...e.flags, ...extraFlags }, refs: e.refs, measure: () => ({ width: 928, height: 1664 }), exists: () => true, random: () => 0.5 });
  return plan.build(["staged_0.png"]);
};

test("the golden holds the graphs it says it holds", () => {
  assert.equal(names.length, 14);
  for (const name of names) {
    const g = golden[name].built.graph || golden[name].built;
    assert.ok(Object.keys(g).length >= 8, name);
    // the pooled krea2 graph is the one that has always named the pack's loaders; no other single graph does
    if (name !== "krea2 pooled") assert.ok(!Object.values(g).some((n) => /MultiGPU/.test(n.class_type)), `${name}: no multi-GPU loader in a single graph`);
    assert.ok(!Object.values(g).some((n) => /Bypass/.test(n.class_type)), name);
  }
  assert.equal(names.filter((n) => golden[n].via === "edit").length, 4);
});

for (const name of names) {
  test(`single placement, ${name}: the graph is the one built before placements existed`, () => {
    const e = golden[name];
    assert.deepEqual(rebuild(e), e.built, "no placement argument");
    assert.deepEqual(rebuild(e, { placement: "single" }), e.built, "--placement single");
  });
}
